CREATE FUNCTION public.request_booking(p_address text,p_feet integer,p_tier integer,p_wreaths integer,p_pathway integer,p_timer boolean,p_storage boolean,p_date date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE roof numeric; extras_cost numeric; surcharge numeric; total numeric; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to save your quote'; END IF; IF length(trim(p_address))<5 OR length(p_address)>300 OR p_feet<100 OR p_feet>5000 OR p_tier NOT BETWEEN 1 AND 3 OR p_wreaths<0 OR p_wreaths>50 OR p_pathway<0 OR p_pathway>5000 OR p_date<current_date THEN RAISE EXCEPTION 'Invalid quote details'; END IF; roof=p_feet*5*CASE p_tier WHEN 1 THEN 1 WHEN 2 THEN 1.35 ELSE 1.75 END; extras_cost=p_wreaths*75+p_pathway*3.5+CASE WHEN p_timer THEN 50 ELSE 0 END+CASE WHEN p_storage THEN 150 ELSE 0 END; surcharge=CASE WHEN to_char(p_date,'MM-DD') BETWEEN '11-20' AND '12-20' THEN round((roof+extras_cost)*.15,2) ELSE 0 END; total=round(roof+extras_cost+surcharge,2); INSERT INTO public.bookings(client_id,address,roof_linear_feet,complexity_tier,extras,estimated_cost,deposit,scheduled_date,status) VALUES(auth.uid(),trim(p_address),p_feet,p_tier,jsonb_build_object('wreaths',p_wreaths,'pathwayFeet',p_pathway,'timer',p_timer,'storage',p_storage),total,round(total*.5,2),p_date,'quoted') RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.request_booking(text,integer,integer,integer,integer,boolean,boolean,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_booking(text,integer,integer,integer,integer,boolean,boolean,date) TO authenticated;